package cn.jingyu.deepseek;

import java.io.IOException;
import java.util.*;

/** A bounded LaTeX subset written as editable Office Math, never raw TeX disguised as a formula. */
public final class OfficeMath {
 private final String source;private int at,depth;
 private static final Map<String,String> SYMBOLS=new HashMap<>();
 static{String[] names={"alpha","beta","gamma","delta","epsilon","theta","lambda","mu","nu","pi","rho","sigma","tau","phi","omega","Gamma","Delta","Theta","Lambda","Pi","Sigma","Phi","Omega","times","cdot","pm","mp","le","leq","ge","geq","ne","neq","approx","equiv","infty","in","notin","subset","subseteq","cup","cap","partial","nabla","rightarrow","to","Rightarrow","leftrightarrow","Leftrightarrow","sum","prod","int","oint","forall","exists","ell","varepsilon","varphi"};String[] values={"α","β","γ","δ","ε","θ","λ","μ","ν","π","ρ","σ","τ","φ","ω","Γ","Δ","Θ","Λ","Π","Σ","Φ","Ω","×","·","±","∓","≤","≤","≥","≥","≠","≠","≈","≡","∞","∈","∉","⊂","⊆","∪","∩","∂","∇","→","→","⇒","↔","⇔","∑","∏","∫","∮","∀","∃","ℓ","ε","φ"};for(int i=0;i<names.length;i++)SYMBOLS.put(names[i],values[i]);String[] extraNames={"zeta","eta","iota","kappa","xi","upsilon","chi","psi","Xi","Upsilon","Psi"};String[] extraValues={"ζ","η","ι","κ","ξ","υ","χ","ψ","Ξ","Υ","Ψ"};for(int i=0;i<extraNames.length;i++)SYMBOLS.put(extraNames[i],extraValues[i]);}
 private OfficeMath(String s){source=s;}
 public static String xml(String source)throws IOException {if(source.length()>20000)throw new IOException("公式过长");OfficeMath p=new OfficeMath(source);String body=p.sequence(false);return "<m:oMath>"+body+"</m:oMath>";}
 private String sequence(boolean grouped)throws IOException {if(++depth>48)throw new IOException("公式嵌套过深");StringBuilder b=new StringBuilder();while(at<source.length()){char c=source.charAt(at);if(c=='}'){if(!grouped)throw new IOException("公式大括号不匹配");at++;depth--;return b.toString();}String base=atom();String sub=null,sup=null;while(at<source.length()&&(source.charAt(at)=='_'||source.charAt(at)=='^')){char kind=source.charAt(at++);String script=atom();if(kind=='_')sub=script;else sup=script;}if(sub!=null&&sup!=null)base="<m:sSubSup><m:e>"+base+"</m:e><m:sub>"+sub+"</m:sub><m:sup>"+sup+"</m:sup></m:sSubSup>";else if(sub!=null)base="<m:sSub><m:e>"+base+"</m:e><m:sub>"+sub+"</m:sub></m:sSub>";else if(sup!=null)base="<m:sSup><m:e>"+base+"</m:e><m:sup>"+sup+"</m:sup></m:sSup>";b.append(base);}depth--;if(grouped)throw new IOException("公式大括号未闭合");return b.toString();}
 private String atom()throws IOException {if(at>=source.length())throw new IOException("公式缺少内容");char c=source.charAt(at++);if(c=='{')return sequence(true);if(c!='\\')return run(String.valueOf(c),false);int start=at;while(at<source.length()&&Character.isLetter(source.charAt(at)))at++;String command=source.substring(start,at);if(command.isEmpty()){if(at>=source.length())throw new IOException("公式转义未完成");char escaped=source.charAt(at++);return run(escaped==','||escaped==';'||escaped=='!'||escaped==' '?' ':escaped,false);}if(command.equals("frac")||command.equals("dfrac")||command.equals("tfrac")){String n=group(),d=group();return "<m:f><m:num>"+n+"</m:num><m:den>"+d+"</m:den></m:f>";}if(command.equals("sqrt")){String degree="";if(at<source.length()&&source.charAt(at)=='['){int end=source.indexOf(']',++at);if(end<0)throw new IOException("根式次数未闭合");degree=run(source.substring(at,end),false);at=end+1;}return "<m:rad><m:radPr><m:degHide m:val=\""+(degree.isEmpty()?"1":"0")+"\"/></m:radPr><m:deg>"+degree+"</m:deg><m:e>"+group()+"</m:e></m:rad>";}if(command.equals("left")||command.equals("right"))return "";if(command.equals("quad")||command.equals("qquad"))return run("  ",true);if(Arrays.asList("text","mathrm","mathbf","operatorname","mathit").contains(command))return group();if(Arrays.asList("sin","cos","tan","log","ln","exp","lim","max","min","det").contains(command))return run(command,true);if(SYMBOLS.containsKey(command))return run(SYMBOLS.get(command),false);throw new IOException("Word暂不支持公式命令 \\"+command+"，可改用PDF保留复杂公式排版。");}
 private String group()throws IOException {while(at<source.length()&&source.charAt(at)==' ')at++;if(at>=source.length()||source.charAt(at++)!='{')throw new IOException("公式参数需要大括号");return sequence(true);}
 private static String run(Object s,boolean plain){return "<m:r>"+(plain?"<m:rPr><m:sty m:val=\"p\"/></m:rPr>":"")+"<m:t xml:space=\"preserve\">"+ArtifactFiles.xml(String.valueOf(s))+"</m:t></m:r>";}
}
